1	// The work item — the queue's one durable object (tasks-dispatch DESIGN §3, §4).
2	// An issue titled `[claudinite-work] <pack>/<task> [qualifier]`, whose labels are
3	// its state, whose body's first line is the task path, and whose optional body
4	// fields (`Not-before`, `Blocked-by`, and a request's `Request` / `Model`) are the
5	// only facts it carries beyond that.
6	//
7	// PURE, and deliberately the whole schema: everything else — anchors, guards,
8	// yields, leashes, verdicts — is computed fresh at every scheduler run and pick from the
9	// engine and the declarations at HEAD (DESIGN §14). The label-and-field vocabulary
10	// here is therefore the compatibility surface across engine versions, which is why
11	// additive change is the strongly preferred shape and a rename needs a migration.
12	//
13	// Parse/serialize of those fields lives here and nowhere else (DESIGN §9).
14	//
15	// The one import, and a frozen constant at that: the pack-rename map, which this
16	// module needs to keep reading titles written before a rename (see parseWorkItemTitle).
17	import { canonicalPackId } from '../../../engine/pack_loader/renamed-packs.mjs';
18	
19	// The title prefix. Disjoint from the slot mechanism's `[claudinite-task]` on
20	// purpose: the two mechanisms coexist per-repo behind `taskScheduler.dispatch`,
21	// and neither may read the other's issues (DESIGN §14, S29).
22	export const WORK_PREFIX = '[claudinite-work]';
23	
24	// --- the canonical vocabulary (DESIGN §4, the migration of #1119) -------------
25	// Every label the machinery writes is one of three things — the item's single
26	// STATUS, its lifelong ORIGIN, or the URGENCY flag — and all of them live in the
27	// `task:` namespace. These are the spellings a reader compares against: decode
28	// first (`statusOf`, `originOf`), then compare, so an item filed by any engine
29	// version answers the same question the same way.
30	export const STATUS_PREFIX = 'task:status:';
31	export const PARK_PREFIX = `${STATUS_PREFIX}needs-human-`;
32	
33	export const STATUS_BLOCKED = `${STATUS_PREFIX}blocked`;
34	export const STATUS_READY = `${STATUS_PREFIX}waiting-for-executor`;
35	export const STATUS_RUNNING_EXECUTOR = `${STATUS_PREFIX}running-executor`;
36	export const STATUS_RUNNING_AGENT = `${STATUS_PREFIX}running-agent`;
37	export const STATUS_NEEDS_HUMAN_ACTION = `${PARK_PREFIX}action`;
38	export const STATUS_NEEDS_HUMAN_DECISION = `${PARK_PREFIX}decision`;
39	export const STATUS_NEEDS_HUMAN_APPROVAL = `${PARK_PREFIX}approval`;
40	export const STATUS_NEEDS_HUMAN_FAILURE = `${PARK_PREFIX}failure`;
41	export const STATUS_DONE = `${STATUS_PREFIX}done`;
42	export const STATUS_REJECTED = `${STATUS_PREFIX}rejected`;
43	
44	// The four statuses an OPEN item may wear before it parks or converges. An open
45	// item wearing no decodable status at all is off the state machine — a torn label
46	// swap's leavings, which the janitor repairs (DESIGN §6.2, §11).
47	export const LIVE_STATUSES = Object.freeze([
48	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
49	]);
50	// The park kinds, in the order a decoder prefers them when an item somehow wears
51	// more than one: `failure` first, because it is the conservative lane — the one
52	// that holds the task's lane rather than letting a broken task keep filing work.
53	export const PARK_KINDS = Object.freeze(['failure', 'action', 'decision', 'approval']);
54	export const PARK_STATUSES = Object.freeze(PARK_KINDS.map((k) => `${PARK_PREFIX}${k}`));
55	export const STATUS_LABELS = Object.freeze([
56	  ...LIVE_STATUSES, ...PARK_STATUSES, STATUS_DONE, STATUS_REJECTED,
57	]);
58	
59	// THE ORIGIN (DESIGN §3, decision §15.29) — who asked for this item, worn for the
60	// item's whole life beside whatever status it holds. Read here; the writers arrive
61	// with the write-side flip.
62	export const ORIGIN_PREFIX = 'task:origin:';
63	export const ORIGIN_PLANNED = `${ORIGIN_PREFIX}planned`;
64	export const ORIGIN_AD_HOC = `${ORIGIN_PREFIX}ad-hoc`;
65	export const ORIGIN_GITHUB = `${ORIGIN_PREFIX}github`;
66	export const ORIGIN_LABELS = Object.freeze([ORIGIN_PLANNED, ORIGIN_AD_HOC, ORIGIN_GITHUB]);
67	
68	// --- the write spellings ------------------------------------------------------
69	// What this engine APPLIES. They are separate from the canonical constants above
70	// for the length of the migration only: reads decode every spelling, writes carry
71	// one, and the flip is these six values changing (#1119).
72	export const BLOCKED = 'task:blocked';
73	export const READY = 'task:ready';
74	export const URGENT = 'task:urgent';
75	export const EXECUTING = 'task:executing';
76	export const AGENT = 'task:agent';
77	export const NEEDS_HUMAN = 'needs-human';
78	
79	// @deprecated Nothing writes this since the approval park: a run that left an
80	// unmerged PR no longer CLOSES as delivered, it parks at
81	// `task:needs-human-approval` and waits to be merged. Kept exported, kept in
82	// `QUEUE_LABELS`, and still read everywhere it was read — closed issues carrying
83	// it are stored data, and a decoder that stopped recognising it would turn every
84	// historical delivered run into an un-outcomed one.
85	export const OUTCOME_DELIVERED = 'outcome:delivered';
86	
87	// @deprecated The pre-2026-08-19 spellings of the two terminals below. Kept
88	// exported so a fielded pack that imports them still loads, and READ wherever an
89	// outcome is decoded: labels are stored data on closed issues fleet-wide, so a
90	// decoder that stopped recognising these would turn every historical run into an
91	// un-outcomed one. Write `TASK_DONE` / `TASK_OBSOLETE`.
92	export const OUTCOME_DONE = 'outcome:done';
93	export const OUTCOME_OBSOLETE = 'outcome:obsolete';
94	
95	// Today's terminal spellings (DESIGN §4, §15.25): the `outcome:` namespace dissolves
96	// into `task:`, one vocabulary for the state machine's live and terminal states
97	// alike. These are what the engine WRITES; the `outcome:*` spellings above are read
98	// forever, because a closed issue keeps whatever it was closed under.
99	export const TASK_DONE = 'task:done';
100	export const TASK_OBSOLETE = 'task:obsolete';
101	
102	// @deprecated The origin marker (DESIGN §15.26). Nothing writes it and nothing
103	// branches on it: whether an item is a task's standing occurrence or an ad-hoc run
104	// is STRUCTURAL — see `isStandingItem` — so a marker that could disagree with the
105	// structure was a second authority over the same fact. Kept exported and inert
106	// because open items filed by an older engine still carry it, and a reader that
107	// choked on an unknown label would fail on exactly those.
108	export const ORIGIN_SCHEDULE = 'origin:schedule';
109	
110	// The TRIAGE SUB-LABELS. `needs-human` says an item is parked; these say what the
111	// human parked with it is expected to DO, which is the whole difference between a
112	// queue a person can skim and one they have to read. Every park wears BOTH:
113	// `needs-human` stays the single state the machine reads (every guard, sweep and
114	// dashboard already turns on it), and the sub-label is the human's routing.
115	//
116	// The four are disjoint by REMEDY, not by cause:
117	//   action   — something outside the code must change: a secret set, a scope
118	//              granted, a routine's prompt or endpoint fixed, an item re-created
119	//              with the parameter it was missing. Mechanical; no judgement.
120	//   decision — the run stopped mid-flight and what happens next is a choice:
121	//              re-queue or abandon, does the half-done work stand, was the
122	//              ceiling violation acceptable.
123	//   approval — the run SUCCEEDED and deliberately left an unmerged PR. The only
124	//              park that is not a fault; the human merges it or closes it.
125	//   failure  — the run broke: a bug, a contract-forbidden shape, a malformed or
126	//              forged item. Someone diagnoses and fixes code.
127	// `failure` is the default a park falls back to, so an unclassified park reads as
128	// "diagnose me" rather than quietly joining the mechanical lane.
129	const triage = (kind) => `task:needs-human-${kind}`;
130	export const NEEDS_HUMAN_ACTION = triage('action');
131	export const NEEDS_HUMAN_DECISION = triage('decision');
132	export const NEEDS_HUMAN_APPROVAL = triage('approval');
133	export const NEEDS_HUMAN_FAILURE = triage('failure');
134	export const TRIAGE_LABELS = Object.freeze([
135	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE,
136	]);
137	// WHICH PARKS HOLD THE TASK'S LANE. A task's open STANDING item is the occurrence
138	// itself, so while one exists the generator files no further occurrence
139	// (`planSchedulerRun` job 1) — which for a park means the task stops being scheduled at
140	// all until a human clears it. That is right for a `failure`: filing a queue of
141	// items that will break the same way helps nobody, and the silence is the signal.
142	// It is wrong for the other three, which are a person's inbox, not a fault in the
143	// task: a PR waiting to be approved, a choice waiting to be made and a secret
144	// waiting to be set must not also stop tomorrow's run.
145	//
146	// A park wearing NO sub-label blocks, which is what makes this safe on the way in:
147	// every item parked by an engine older than the sub-labels, and every kind word a
148	// future engine invents that this one does not know, holds the lane rather than
149	// silently letting a broken task keep filing work.
150	export const isBlockingPark = (item) => statusOf(item) === STATUS_NEEDS_HUMAN_FAILURE;
151	
152	// --- the decode (DESIGN §4, "legacy spellings — written never, read forever") --
153	// Labels are STORED DATA: open items filed by a fielded engine wear its spellings,
154	// closed items keep theirs forever, and members converge on their own schedules. So
155	// every reader here goes through one pass that maps every spelling ever written
156	// straight to today's — never through a literal comparison against one of them.
157	const LEGACY_STATUS = new Map([
158	  [BLOCKED, STATUS_BLOCKED],
159	  [READY, STATUS_READY],
160	  [EXECUTING, STATUS_RUNNING_EXECUTOR],
161	  [AGENT, STATUS_RUNNING_AGENT],
162	  [TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
163	  [TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
164	]);
165	
166	const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;
167	
168	// The park an issue's labels name, canonical, or null. Both shapes decode here:
169	// today's single `task:status:needs-human-<kind>` and the legacy pair
170	// (`needs-human` plus a sub-label). A kind nobody here knows — a bare legacy park,
171	// or a word a newer engine invented — reads as `failure`, the conservative lane.
172	function parkOf(names) {
173	  const kinds = [
174	    ...names.filter((n) => n.startsWith(PARK_PREFIX)).map((n) => n.slice(PARK_PREFIX.length)),
175	    ...names.map((n) => LEGACY_PARK_RE.exec(n)?.[1]).filter(Boolean),
176	  ];
177	  if (!kinds.length && !names.includes(NEEDS_HUMAN)) return null;
178	  return `${PARK_PREFIX}${PARK_KINDS.find((k) => kinds.includes(k)) ?? 'failure'}`;
179	}
180	
181	// Every distinct status an issue's labels decode to. One entry per status, so an
182	// item mid-flip — wearing a legacy spelling beside its canonical one — reads as the
183	// ONE status it is, and only genuinely conflicting labels read as more than one
184	// (the dashboard's `torn`).
185	export function statusesOn(issue) {
186	  const names = labelNames(issue);
187	  const out = new Set();
188	  const park = parkOf(names);
189	  if (park) out.add(park);
190	  for (const n of names) {
191	    if (STATUS_LABELS.includes(n) && !n.startsWith(PARK_PREFIX)) out.add(n);
192	    else if (LEGACY_STATUS.has(n)) out.add(LEGACY_STATUS.get(n));
193	  }
194	  return [...out];
195	}
196	
197	// THE status an issue wears, canonical, or null for one wearing none. A park wins
198	// over anything else present: a torn transition that left a state label beside a
199	// park must read as parked, or the queue would pick up an item a human owns.
200	export function statusOf(issue) {
201	  const worn = statusesOn(issue);
202	  return worn.find((s) => s.startsWith(PARK_PREFIX))
203	    ?? STATUS_LABELS.find((s) => worn.includes(s))
204	    ?? null;
205	}
206	
207	export const isStatus = (issue, status) => statusOf(issue) === status;
208	export const isParked = (issue) => (statusOf(issue) ?? '').startsWith(PARK_PREFIX);
209	export const parkKindOf = (issue) =>
210	  (isParked(issue) ? statusOf(issue).slice(PARK_PREFIX.length) : null);
211	
212	// The origin an issue wears, or null. Unlike the status there is no legacy
213	// spelling to fold in: `origin:schedule` is inert stored data (see ORIGIN_SCHEDULE),
214	// and reading it as an origin would put a marker nothing writes back into play.
215	export const originOf = (issue) =>
216	  labelNames(issue).find((n) => ORIGIN_LABELS.includes(n)) ?? null;
217	
218	// Every spelling that MEANS `status` — what a transition out of it has to clear,
219	// since the item may wear any engine's. Leaving a park clears every park spelling
220	// whatever its kind: a re-queue takes the item out of the human's hands entirely.
221	export function spellingsOf(status) {
222	  if (String(status ?? '').startsWith(PARK_PREFIX)) {
223	    return [...PARK_STATUSES, ...PARK_KINDS.map((k) => `task:needs-human-${k}`), NEEDS_HUMAN];
224	  }
225	  const legacy = [...LEGACY_STATUS].filter(([, canonical]) => canonical === status).map(([l]) => l);
226	  return [status, ...legacy];
227	}
228	
229	// A kind word (from a worker's own triage marker, or a call site) to its label.
230	// Anything unrecognised is a `failure`: a worker that misspells its class has a
231	// bug, which is exactly what that lane means.
232	export const triageLabelFor = (kind) =>
233	  (TRIAGE_LABELS.includes(triage(kind)) ? triage(kind) : NEEDS_HUMAN_FAILURE);
234	
235	
236	// The stored-data rename rule, decode side: every spelling ever written maps
237	// STRAIGHT to the canonical word, in one pass — including `outcome:delivered`,
238	// which nothing writes any more but closed issues carry forever.
239	const OUTCOME_WORDS = new Map([[STATUS_DONE, 'done'], [STATUS_REJECTED, 'obsolete']]);
240	
241	// The one outcome an issue's labels carry, as the canonical word ('done',
242	// 'delivered', 'obsolete') or null. Everything that tallies or renders outcomes
243	// decodes through here, so a spelling change is one map entry and not a sweep.
244	export function outcomeOf(issue) {
245	  // `statusesOn` rather than `statusOf`: a closed item's terminal write is its
246	  // outcome even when a park label stands beside it, and park precedence is a
247	  // question about LIVE items — what the queue may pick up — not about history.
248	  const worn = statusesOn(issue);
249	  for (const [status, word] of OUTCOME_WORDS) if (worn.includes(status)) return word;
250	  return hasLabel(issue, OUTCOME_DELIVERED) ? 'delivered' : null;
251	}
252	
253	// --- the request vocabulary, retired (DESIGN §4's legacy table, §16.1) --------
254	// @deprecated The five labels the SHADOW-ITEM request model used. The mark is
255	// `task:origin:ad-hoc` now and the marked issue is the item itself, so nothing here
256	// applies these — but they are read forever: `claude-task` is still accepted as a
257	// mark (a person with it in muscle memory, a template that carries it), and an
258	// issue whose shadow item is still draining wears `claude-queued`.
259	//
260	// What survives the retirement is the reason the mark is a LABEL at all: it must be
261	// appliable from the issue page on a phone, and it is write-gated by the platform —
262	// applying a label needs triage or write access — which is the first half of the
263	// security story (the second is the precondition's permission read at pickup,
264	// §16.4). The parameters that were labels are body fields now, gated on the
265	// author's push access instead (`parseRequestFields`).
266	export const REQUEST_LABEL = 'claude-task';
267	export const QUEUED_LABEL = 'claude-queued';
268	export const IN_REVIEW_LABEL = 'claude-in-review';
269	export const MODEL_LABEL_PREFIX = 'claude-model:';
270	
271	// The merge authorization (§16.11): the asker says up front that this request's
272	// change may land without their approval WHEN ITS DIFF IS NARROW — the run still
273	// judges the diff, and a wide one parks for review exactly as an unauthorized
274	// request does. Consumed with the mark like the model labels, so each ask
275	// authorizes afresh and a label left by an earlier ask never carries into a new one.
276	export const AUTOMERGE_LABEL = 'claude-automerge';
277	
278	// The families a request may ask for, and the one it gets when it asks for
279	// nothing. `none` is not among them: a request is implemented by a session, so an
280	// agentless family would name a run that cannot happen.
281	export const REQUEST_MODELS = Object.freeze(['opus', 'sonnet', 'haiku']);
282	export const DEFAULT_REQUEST_MODEL = 'opus';
283	
284	export const MODEL_LABELS = REQUEST_MODELS.map((f) => `${MODEL_LABEL_PREFIX}${f}`);
285	
286	// @deprecated The set the shadow-item model ensured. Nothing ensures it now — the
287	// entry point is `task:origin:ad-hoc`, which the queue's own set carries — and it
288	// stays exported because a fielded pack version may still import it.
289	export const REQUEST_LABELS = [
290	  { name: REQUEST_LABEL, color: '1d76db', description: 'Claudinite: implement this issue — the next scheduler run queues a run for it' },
291	  { name: QUEUED_LABEL, color: 'fbca04', description: 'Claudinite: a work item exists for this issue' },
292	  { name: IN_REVIEW_LABEL, color: '5319e7', description: 'Claudinite: a pull request is open for this issue, waiting on a person' },
293	  { name: AUTOMERGE_LABEL, color: '0e8a16', description: 'Claudinite: land this request without approval if its diff is narrow (docs, tests, comments, code in one directory)' },
294	  ...REQUEST_MODELS.map((f) => ({
295	    name: `${MODEL_LABEL_PREFIX}${f}`, color: 'ededed',
296	    description: `Claudinite: run this request at the ${f} family`,
297	  })),
298	];
299	
300	// The model a marked issue asks for, from the labels standing on it. An
301	// unrecognised family falls back to the default rather than failing the request:
302	// a run nobody can start would look accepted forever. Where several are present the
303	// order is REQUEST_MODELS' — the labels are consumed at adoption (§16.3), so the
304	// only way to hold two is to apply two for the same ask.
305	export const requestModelFromLabels = (labels = []) => {
306	  const asked = labels.filter((l) => l.startsWith(MODEL_LABEL_PREFIX)).map((l) => l.slice(MODEL_LABEL_PREFIX.length));
307	  return REQUEST_MODELS.find((f) => asked.includes(f)) ?? DEFAULT_REQUEST_MODEL;
308	};
309	
310	// The four state labels an open item may wear. An open item wearing none of them
311	// and no `needs-human` is off the state machine entirely — a torn label swap's
312	// leavings, which the janitor repairs (DESIGN §6.2, §11).
313	export const STATE_LABELS = [BLOCKED, READY, EXECUTING, AGENT];
314	
315	// The canonical statuses the same four decode to — what a reader tests against,
316	// since an item may wear either engine's spelling (`statusesOn`).
317	export { LIVE_STATUSES as STATE_STATUSES };
318	
319	// Every label this mechanism applies, with the colour and description a bootstrap
320	// one-off would have given it. Ensured create-if-missing before anything is
321	// applied: GitHub 422s when you apply an unknown label and never creates one on
322	// demand, so the thing that assigns a label guarantees it first.
323	export const QUEUE_LABELS = [
324	  { name: BLOCKED, color: 'c5def5', description: 'Claudinite queue: waiting on Blocked-by and/or Not-before' },
325	  { name: READY, color: '0e8a16', description: 'Claudinite queue: available for an executor to pick up' },
326	  { name: URGENT, color: 'd93f0b', description: 'Claudinite queue: pick this before any non-urgent item' },
327	  { name: EXECUTING, color: 'fbca04', description: 'Claudinite queue: an executor holds the claim' },
328	  { name: AGENT, color: '1d76db', description: 'Claudinite queue: an agent session owns this item' },
329	  { name: NEEDS_HUMAN, color: 'b60205', description: 'Claudinite queue: parked for a human — the one triage state' },
330	  { name: NEEDS_HUMAN_ACTION, color: 'b60205', description: 'Claudinite triage: a human must change something outside the code' },
331	  { name: NEEDS_HUMAN_DECISION, color: 'd93f0b', description: 'Claudinite triage: a human must choose what happens next' },
332	  { name: NEEDS_HUMAN_APPROVAL, color: '5319e7', description: 'Claudinite triage: succeeded and left an unmerged PR to approve' },
333	  { name: NEEDS_HUMAN_FAILURE, color: 'b60205', description: 'Claudinite triage: the run broke — diagnose and fix' },
334	  { name: TASK_DONE, color: '0e8a16', description: 'Claudinite queue: succeeded, nothing pending' },
335	  { name: OUTCOME_DELIVERED, color: '5319e7', description: 'Claudinite queue: succeeded and left a live artifact the world still has to act on' },
336	  { name: TASK_OBSOLETE, color: 'ededed', description: 'Claudinite queue: never ran — the precondition said no, or the task is gone' },
337	  // The canonical vocabulary, ensured BEFORE anything writes it (#1119): a label
338	  // that does not exist 422s the write that would apply it, and the ensure pass and
339	  // the flip that starts applying these reach a member in separate converges.
340	  { name: STATUS_BLOCKED, color: 'c5def5', description: 'Claudinite queue: waiting on Blocked-by and/or Not-before' },
341	  { name: STATUS_READY, color: '0e8a16', description: 'Claudinite queue: available for an executor to pick up' },
342	  { name: STATUS_RUNNING_EXECUTOR, color: 'fbca04', description: 'Claudinite queue: an executor holds the claim' },
343	  { name: STATUS_RUNNING_AGENT, color: '1d76db', description: 'Claudinite queue: an agent session owns this item' },
344	  { name: STATUS_NEEDS_HUMAN_ACTION, color: 'b60205', description: 'Claudinite queue: parked — a human must change something outside the code' },
345	  { name: STATUS_NEEDS_HUMAN_DECISION, color: 'd93f0b', description: 'Claudinite queue: parked — a human must choose what happens next' },
346	  { name: STATUS_NEEDS_HUMAN_APPROVAL, color: '5319e7', description: 'Claudinite queue: parked — succeeded and left an unmerged PR to approve' },
347	  { name: STATUS_NEEDS_HUMAN_FAILURE, color: 'b60205', description: 'Claudinite queue: parked — the run broke, diagnose and fix' },
348	  { name: STATUS_DONE, color: '0e8a16', description: 'Claudinite queue: succeeded, nothing pending' },
349	  { name: STATUS_REJECTED, color: 'ededed', description: 'Claudinite queue: never ran — the precondition said no, or the task is gone' },
350	  { name: ORIGIN_PLANNED, color: 'c2e0c6', description: 'Claudinite queue: filed by the schedule — a task\'s own occurrence' },
351	  { name: ORIGIN_AD_HOC, color: 'bfd4f2', description: 'Claudinite queue: asked for by a person — a one-issue request or a hand-created run' },
352	  { name: ORIGIN_GITHUB, color: 'd4c5f9', description: 'Claudinite queue: filed by the platform itself — a workflow reporting its own failure' },
353	];
354	
355	// GitHub hands labels back as objects on the issues API and as bare strings in
356	// some fixtures; accept either.
357	export const labelNames = (issue) =>
358	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
359	
360	export const hasLabel = (issue, name) => labelNames(issue).includes(name);
361	
362	// Title. The optional qualifier exists ONLY for deliberately concurrent items —
363	// a fan-out naming its target — and it is part of the identity the same-title
364	// mutex reads (DESIGN §6.1). Nothing ever encodes a date here: that was the slot
365	// grammar, and the issue number is the identity (DESIGN §5).
366	export const workItemTitle = ({ pack, task, qualifier = null }) =>
367	  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;
368	
369	// pack and task ids are single path segments; the qualifier is whatever follows.
370	const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;
371	
372	// The pack half is canonicalized on the way out. A work item's title is STORED
373	// DATA — it sits on an open GitHub issue that outlives any one converge — so items
374	// filed before a pack was renamed still carry the old spelling. Read literally, the
375	// scheduler run would not recognise its own live item, would file a second one beside it, and
376	// would leave the first orphaned in the queue with nothing ever draining it.
377	export function parseWorkItemTitle(title) {
378	  const m = TITLE_RE.exec(String(title ?? '').trim());
379	  return m ? { pack: canonicalPackId(m[1]), task: m[2], qualifier: m[3]?.trim() || null } : null;
380	}
381	
382	export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;
383	
384	// The `<pack>/<task>` id a WORKER PATH names — the identity half a marked issue's
385	// title cannot carry (DESIGN §16.1), read off the path its machine block names. Two
386	// shapes, because tasks have two homes: the `tasks/` slot a declared pack contributes,
387	// and the queue's own built-in root. The `.claudinite/shared/` prefix is optional in
388	// both — a member's mount is there and the canon runs its own tree.
389	//
390	// THE BUILT-IN ROOT HAS TWO SPELLINGS, and both are permanent. The surface moved from
391	// `engine/scheduler/` to the tasks pack (#1317), so a live item minted before the move
392	// still names the engine path while every new one names the pack path; the wire id
393	// either produces is unchanged, which is what the move promised. Stored data is
394	// renamed on the DECODE side or it stops decoding, and here that failure is silent:
395	// this is the fallback for a marked issue, whose title is the requester's own words,
396	// so a path that yields null leaves the item unattributable rather than rejected.
397	//
398	// It is a PARSE, not a lookup: anything that must know the task exists at HEAD
399	// resolves the path against the discovered task set instead (the executor does).
400	const PACK_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/tasks\/([^/]+)\/[^/]+$/;
401	const BUILT_IN_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?(?:engine\/scheduler|packs\/claudinite-tasks)\/queue\/tasks\/([^/]+)\/[^/]+$/;
402	
403	export function taskIdFromPath(path) {
404	  const p = String(path ?? '');
405	  const pack = PACK_TASK_PATH_RE.exec(p);
406	  if (pack) return { pack: canonicalPackId(pack[1]), task: pack[2] };
407	  const builtIn = BUILT_IN_TASK_PATH_RE.exec(p);
408	  return builtIn ? { pack: 'engine', task: builtIn[1] } : null;
409	}
410	
411	// STANDING OR AD-HOC, DERIVED (DESIGN §15.26). A task's standing item is the one
412	// the generator files at an anchor: its title names the task and nothing else, and
413	// the task it names is on a calendar. Everything else is ad-hoc — a `manual` task
414	// (which has no anchor to stand for) and every qualified item (a fan-out target, a
415	// request naming its issue), each of which may legitimately run beside the
416	// occurrence rather than being it.
417	//
418	// It is read off the item and the declaration at HEAD rather than off a label the
419	// creator applied, because the two could disagree: a marker says what its writer
420	// believed, the structure says what the item IS, and the guards that consume this
421	// (the occurrence guard, the dedupe, the `after` yield) are only sound on the
422	// second. `frequency` is the declared frequency of the task the title names —
423	// absent when the repo no longer carries it, which is ad-hoc by the same rule.
424	export function isStandingItem(item, frequency) {
425	  const parsed = parseWorkItemTitle(item?.title ?? item);
426	  return !!parsed && parsed.qualifier === null && frequency != null && frequency !== 'manual';
427	}
428	
429	// --- comment markers ----------------------------------------------------------
430	// The three comments the protocol reads back. They are HTML comments so a human
431	// reading the item sees prose, and they are here — with the labels and the body
432	// fields — because together they ARE the item's vocabulary, the one compatibility
433	// surface across engine versions (DESIGN §14).
434	//
435	// The CLAIM comment carries who and when (executor identity is an unbounded set
436	// and must never become a label). The HANDOFF comment names the session and the
437	// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
438	// scoped to: every claim before it is dead, and arbitrating over dead claims makes
439	// one outrank every future live claimant — the item then livelocks through reclaim
440	// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
441	export const CLAIM_MARKER = '<!-- claudinite-claim -->';
442	export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
443	export const EPISODE_MARKER = '<!-- claudinite-episode -->';
444	
445	// --- the body -----------------------------------------------------------------
446	
447	export const NOT_BEFORE_FIELD = 'Not-before';
448	export const BLOCKED_BY_FIELD = 'Blocked-by';
449	
450	// The three fields a REQUEST item carries (DESIGN §16.3, §16.11). `Request` is the issue this
451	// run implements — the whole payload, since the request task has no code-work phase
452	// to hand one over. `Model` is the family the asker chose, copied here by the scheduler run
453	// from a write-gated label and read only by a task that declares
454	// `model_from_request`; it is the first thing an item carries that defines
455	// behaviour, which is why it is fenced rather than waved through (§16.7).
456	export const REQUEST_FIELD = 'Request';
457	export const MODEL_FIELD = 'Model';
458	
459	// `Task` is the TARGETING field (DESIGN §16, the one-issue request): which task a
460	// marked issue asks for, as `<pack>/<task>`. Absent, the ask is the built-in
461	// request implementer, which is what an ordinary "implement this issue" mark means.
462	// It rides the same author gate as `Model` and `Merge`: naming a task is choosing
463	// what runs, and a body is editable by whoever opened the issue.
464	export const TASK_FIELD = 'Task';
465	
466	// `Merge` is the asker's standing authorization, copied here from the
467	// write-gated `claude-automerge` label. Its one value is `if-narrow`: the run may
468	// land its own pull request when the diff classifier calls the diff narrow, and
469	// must park for approval otherwise. An absent field is the default — never merge —
470	// so an item an older scheduler run wrote reads as unauthorized rather than as authorized.
471	export const MERGE_FIELD = 'Merge';
472	export const MERGE_IF_NARROW = 'if-narrow';
473	
474	// The heading the delivered-artifacts section carries in a work item body. One
475	// home, because it is written in three places and MATCHED when a re-entrant run
476	// updates the section it already wrote.
477	export const DELIVERED_HEADING = 'Delivered by code-work';
478	
479	// The same heading as earlier renames spelled it. A live item's body still carries
480	// whichever word was current when its section was first written, and matching only
481	// today's would append a SECOND section rather than updating that one.
482	export const LEGACY_DELIVERED_HEADINGS = Object.freeze([
483	  'Delivered by prework',
484	  'Delivered by code_work',
485	]);
486	
487	// --- the machine block (DESIGN §16.1, §16.3) ----------------------------------
488	// A one-issue request's item IS the issue somebody marked, so the item's fields
489	// share a body a person authored and keeps editing. They live in one delimited
490	// block, appended at adoption and rewritten in place after that: everything outside
491	// it belongs to the human, everything inside it to the machine, and a parser that
492	// read the whole body would take a sentence of prose for a field.
493	//
494	// A `[claudinite-work]` item has no block — its whole body is the machine's — so
495	// every reader here falls back to the whole text, which is what keeps items filed
496	// before the one-issue model draining unchanged.
497	export const MACHINE_BLOCK_START = '<!-- claudinite-item -->';
498	export const MACHINE_BLOCK_END = '<!-- /claudinite-item -->';
499	
500	const BLOCK_RE = /<!-- claudinite-item -->\n?([\s\S]*?)\n?<!-- \/claudinite-item -->/;
501	
502	// The machine's half of a body, or null where there is no block at all.
503	export const machineBlockOf = (body) => BLOCK_RE.exec(String(body ?? ''))?.[1] ?? null;
504	
505	// The machine's half to read fields out of: the block where there is one, the whole
506	// body otherwise.
507	export const itemFieldText = (body) => machineBlockOf(body) ?? String(body ?? '');
508	
509	// Replace the block, or append one to a body that has none. The human's text is
510	// never rewritten — an append lands after it, separated by a blank line.
511	export function withMachineBlock(body, block) {
512	  const text = String(body ?? '');
513	  const wrapped = `${MACHINE_BLOCK_START}\n${block.replace(/\s*$/, '')}\n${MACHINE_BLOCK_END}`;
514	  if (BLOCK_RE.test(text)) return text.replace(BLOCK_RE, wrapped);
515	  return `${text.replace(/\s*$/, '')}\n\n${wrapped}\n`;
516	}
517	
518	// Apply an edit to whichever half is the machine's. Every writer that reshapes an
519	// item body — a Context section, code-work's delivered list, a stamped
520	// `Not-before` — goes through here, so it edits the block on a marked issue and the
521	// whole body on a `[claudinite-work]` item, with one call site either way.
522	export function editItemBody(body, edit) {
523	  const block = machineBlockOf(body);
524	  return block === null ? edit(String(body ?? '')) : withMachineBlock(body, edit(block));
525	}
526	
527	// The human's half of a body — everything the machine block is not. A marked
528	// issue's PARAMETERS are read from here and never from the block: re-asking clears
529	// the status and leaves the previous run's block standing, and a parser that read
530	// the whole body would find that stale copy beside the person's own field.
531	export const humanTextOf = (body) => String(body ?? '').replace(BLOCK_RE, '').trim();
532	
533	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
534	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
535	const REQUEST_RE = /^Request:[ \t]*#?(\d+)/m;
536	const MODEL_RE = /^Model:[ \t]*(\S+)/m;
537	const MERGE_RE = /^Merge:[ \t]*(\S+)/m;
538	
539	// Build a work item body. The first line is the task path — the only thing an
540	// executor reads to locate the worker, validated in code before anything trusts
541	// it. Everything behavior-defining (model, ceiling, worker content, code-work
542	// command) is read from the tracked task files at HEAD, never from here.
543	export function workItemBody({
544	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
545	  request = null, model = null, merge = null,
546	}) {
547	  const lines = [taskPath, ''];
548	  const fields = [];
549	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
550	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
551	  if (request) fields.push(`${REQUEST_FIELD}: #${request}`);
552	  if (model) fields.push(`${MODEL_FIELD}: ${model}`);
553	  if (merge) fields.push(`${MERGE_FIELD}: ${merge}`);
554	  if (fields.length) lines.push(...fields, '');
555	  lines.push('Execute the Claudinite task above.');
556	  if (context.length) {
557	    lines.push(
558	      'The Context section below is binding scope — do not re-decide it.',
559	      '',
560	      '### Context',
561	      ...context.map((c) => `- ${c}`),
562	    );
563	  }
564	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
565	  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
566	  return lines.join('\n') + '\n';
567	}
568	
569	// The `Blocked-by` numbers a body names, from a work item's body or from an
570	// ORDINARY issue's — a request marked for implementation states what it waits on in
571	// the same field spelling, and adoption carries it onto the item it births (§16.11).
572	export function parseBlockedBy(body) {
573	  const bb = BLOCKED_BY_RE.exec(String(body ?? ''))?.[1] ?? '';
574	  return [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
575	}
576	
577	// Parse an item body back into the facts the scheduler run and the executor read. A body
578	// with no first line, or whose fields are absent, yields nulls — absence is
579	// meaningful everywhere here and is never filled in with a default.
580	export function parseWorkItemBody(body) {
581	  const text = itemFieldText(body);
582	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
583	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
584	  const blockedBy = parseBlockedBy(text);
585	  const request = REQUEST_RE.exec(text) ? Number(REQUEST_RE.exec(text)[1]) : null;
586	  // An unrecognised family reads as absent rather than as itself: the item's model
587	  // is behaviour-defining, so the only values that leave this parser are ones the
588	  // engine can actually dispatch at (§16.7).
589	  const askedModel = MODEL_RE.exec(text)?.[1] ?? null;
590	  const model = REQUEST_MODELS.includes(askedModel) ? askedModel : null;
591	  // Same fencing as the model: an unrecognised authorization reads as absent, and
592	  // absent is the safe end of this field — a run that cannot read its permission
593	  // opens a pull request and waits.
594	  const askedMerge = MERGE_RE.exec(text)?.[1] ?? null;
595	  const merge = askedMerge === MERGE_IF_NARROW ? askedMerge : null;
596	  return { taskPath, notBefore: nb, blockedBy, request, model, merge };
597	}
598	
599	// WHAT A MARKED ISSUE ASKS FOR (DESIGN §16.3, §16.7, §16.11) — read from the
600	// person's own text at every adoption, so each ask names its parameters afresh and
601	// nothing stale outranks a new one.
602	//
603	// `gated` is whether the issue's AUTHOR holds push access. A body is editable by
604	// whoever opened the issue where a label was write-gated by the platform, so the
605	// three behaviour-defining fields are honoured only for an author who could have
606	// applied them as labels anyway; an ungated ask still runs, at the default task and
607	// model and with no authorization to land anything.
608	export function parseRequestFields(body, { gated = false } = {}) {
609	  const text = humanTextOf(body);
610	  const asked = {
611	    task: /^Task:[ \t]*(\S+)/m.exec(text)?.[1] ?? null,
612	    model: MODEL_RE.exec(text)?.[1] ?? null,
613	    automerge: /^Automerge:[ \t]*(\S+)/m.exec(text)?.[1]?.toLowerCase() ?? null,
614	  };
615	  const blockedBy = parseBlockedBy(text);
616	  const notBefore = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
617	  if (!gated) return { task: null, model: null, merge: null, blockedBy, notBefore, ungated: Object.values(asked).some(Boolean) };
618	  return {
619	    task: /^[^/\s]+\/[^/\s]+$/.test(asked.task ?? '') ? asked.task : null,
620	    // An unrecognised family reads as absent rather than failing the request: a run
621	    // nobody can start would look accepted forever.
622	    model: REQUEST_MODELS.includes(asked.model) ? asked.model : null,
623	    merge: ['if-narrow', 'yes', 'true'].includes(asked.automerge) ? MERGE_IF_NARROW : null,
624	    blockedBy,
625	    notBefore,
626	    ungated: false,
627	  };
628	}
629	
630	// The item's own `### Context` bullets, in order — the binding scope a hand-created
631	// item was born with. Read back rather than kept only for the agent to read,
632	// because an operator's PARAMETERS ride here: `create-work-item --context
633	// "REPOS=Alpha Beta"` is how a forced run says what it is running on, and the
634	// executor hands these lines to code-work as `CLAUDINITE_CONTEXT`.
635	//
636	// A section runs to the next `### ` heading or to the end of the body — the same
637	// bounds `withSection` writes to — and only `- ` bullets count, so the prose
638	// framing around a section contributes nothing.
639	function sectionLines(body, heading) {
640	  const lines = String(body ?? '').split('\n');
641	  const at = lines.findIndex((l) => l.trim() === `### ${heading}`);
642	  if (at === -1) return [];
643	  const out = [];
644	  for (const line of lines.slice(at + 1)) {
645	    if (line.startsWith('### ')) break;
646	    const m = /^-[ \t]+(.*)$/.exec(line);
647	    if (m) out.push(m[1].trim());
648	  }
649	  return out;
650	}
651	
652	export const parseContextLines = (body) => sectionLines(body, 'Context');
653	
654	// --- the roll's record ----------------------------------------------------------
655	
656	// The section a no-go roll keeps on the item: the last declined reason and the next
657	// wake, REPLACED on every roll (the item is a status line, not a log — the timeline
658	// carries the history). Serializer and parser live together so the shape has one
659	// home; the executor writes it, and anything answering "why didn't it run" — the
660	// dashboard above all — reads it back.
661	export const LAST_VERDICT_HEADING = 'Last verdict';
662	
663	export function lastVerdictLines({ at, reason, until }) {
664	  const lines = [`${at} — the precondition declined: ${reason}`];
665	  if (until) lines.push(`Asked again at ${until}.`);
666	  return lines;
667	}
668	
669	export function parseLastVerdict(body) {
670	  const lines = sectionLines(body, LAST_VERDICT_HEADING);
671	  // The reason may carry the separator itself, so the split is on the FIRST match.
672	  const first = /^(.*?) — the precondition declined: ([\s\S]*)$/.exec(lines[0] ?? '');
673	  if (!first) return null;
674	  const until = lines.map((l) => /^Asked again at (.*?)\.?$/.exec(l)).find(Boolean)?.[1] ?? null;
675	  return { at: first[1], reason: first[2], until };
676	}
677	
678	// Fold a second set of Context lines into the first, keeping order and dropping
679	// exact duplicates. Both sides are real scope — the item carries what its creator
680	// bound it to, the precondition adds what this occurrence found — and a set-write
681	// from either side would drop the other's.
682	export const mergeContext = (...groups) => [...new Set(groups.flat().filter((l) => l && l.trim()))];
683	
684	// Stamp (or clear) `Not-before` on an existing body, in place where the field is
685	// already present and directly under the task path otherwise. Text surgery rather
686	// than a rebuild: the body also carries the creating precondition's Context and
687	// code-work's Delivered section, which belong to whoever wrote them.
688	export function withNotBefore(body, iso) {
689	  const text = String(body ?? '');
690	  if (NOT_BEFORE_RE.test(text)) {
691	    return iso
692	      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
693	      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
694	  }
695	  if (!iso) return text;
696	  const lines = text.split('\n');
697	  const at = lines.findIndex((l) => l.trim() !== '');
698	  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
699	  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
700	  return lines.join('\n');
701	}
702	
703	// Set a section of an item body (the Context, code-work's Delivered, the agent's Why)
704	// — replacing one of the same heading if it is already there, appending otherwise.
705	//
706	// REPLACING IS THE WHOLE POINT, and appending was a live bug (#879). Every standing
707	// item is born carrying a `### Context`, and the hand-off writes Context again — so
708	// an append leaves TWO sections of that name, while the session is told to read "the
709	// issue's Context section", singular. The one it reads first is then the scheduler run's birth
710	// note and the binding scope is in the other, which fails silently whichever section
711	// the agent picks. It also grows: an item re-queued through hand-off twice carried a
712	// third.
713	//
714	// A section runs to the next `### ` heading or to the end of the body, so a replaced
715	// section keeps its position rather than migrating to the bottom — the body stays in
716	// the order a reader learned it.
717	// `aliases` are older spellings of the SAME heading. The section is rewritten under
718	// `heading`, but located by any of them, so a body written before a rename is updated
719	// in place instead of gaining a second section.
720	export function withSection(body, heading, lines, aliases = []) {
721	  if (!lines.length) return body;
722	  const text = String(body ?? '').replace(/\s*$/, '');
723	  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
724	  const existing = text.split('\n');
725	  const wanted = new Set([heading, ...aliases].map((h) => `### ${h}`));
726	  const at = existing.findIndex((l) => wanted.has(l.trim()));
727	  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
728	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
729	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
730	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
731	}
732

